class VLAConfig(PreTrainedConfig):
    r"""
    A unified configuration class for VLA (Vision-Language-Action) specific parameters.
    This class centralizes all action-related, state-related, and flow-matching parameters
    that extend a VLM into a VLA model.

    Args:
        action_hidden_size (`int`, *optional*, defaults to 2048):
            Hidden dimension for the action head / action expert MLP.
        state_hidden_size (`int`, *optional*, defaults to 2048):
            Hidden dimension for the state encoder MLP.
        num_experts (`int`, *optional*, defaults to 4):
            Number of MoE experts used in the action/state mixture-of-experts layers.
        experts (`list`, *optional*):
            Expert configuration list. Each element describes one expert's architecture.
        dof_config (`dict`, *optional*):
            Degrees-of-freedom configuration describing the robot's action space
            (e.g. joint dimensions, gripper dims, etc.).
        noise_scheduler (`dict`, *optional*):
            Configuration for the diffusion / flow-matching noise scheduler
            (e.g. num_train_timesteps, beta_schedule).
        dim_inputs (`tuple[int, int]`, *optional*, defaults to `(1536, 1536)`):
            Input projection dimensions for the (state, action) tokens respectively.
        attention_moe (`bool`, *optional*, defaults to `False`):
            Whether to apply MoE routing on the attention module.
        mlp_moe (`bool`, *optional*, defaults to `False`):
            Whether to apply MoE routing on the MLP module.
        norm_moe (`bool`, *optional*, defaults to `False`):
            Whether to apply MoE routing on the normalization layers.
        mot_opt (`bool`, *optional*, defaults to `False`):
            Whether to enable Mixture-of-Tokens optimization.
        ar_loss_weight (`float`, *optional*, defaults to 1.0):
            Weight of the auto-regressive language modelling loss during joint training.
        use_state_string_representation (`bool`, *optional*, defaults to `False`):
            Whether to encode robot states as string tokens instead of continuous embeddings.
        use_adarms (`bool`, *optional*, defaults to `False`):
            Whether to use AdaRMS conditioning (adaptive RMS-norm conditioned on a context vector).
        proj_with_mask (`bool`, *optional*, defaults to `True`):
            Whether to apply a binary mask when projecting action tokens into the LLM space.
        adarms_cond_dim (`int`, *optional*):
            Dimension of the conditioning vector fed into AdaRMS layers.
            Defaults to `action_hidden_size` when `None`.
        action_horizon_flow (`int`, *optional*, defaults to 32):
            Number of flow-matching denoising steps used during action inference.
        causal_action_attention_mask (`bool`, *optional*, defaults to `False`):
            Whether to apply a causal mask over action token self-attention.
        use_flow_action_expert (`bool`, *optional*, defaults to `True`):
            Whether to use the dedicated flow-matching action expert head.
        use_x_pred (`bool`, *optional*, defaults to `False`):
            Whether to predict the clean sample x0 directly instead of the velocity/noise.
        attn_deterministic (`bool`, *optional*, defaults to `False`):
            Whether to force deterministic (non-Flash) attention for reproducibility.
        use_x_loss (`bool`, *optional*, defaults to `False`):
            Whether to add an auxiliary x0-prediction loss during flow-matching training.
        refiner (`dict`, *optional*):
            Residual refiner (``enabled``, ``num_steps``, ``timestep``): one extra
            action-branch pass on twin weights after flow sampling. See
            ``wall_x.model.core.refiner``.

    Example::

        >>> from wall_x.model.qact.qwen3_5.configuration_qwen3_5 import VLAConfig
        >>> vla_cfg = VLAConfig(action_hidden_size=1024, dof_config={"arm": 7, "gripper": 1})
    """

    model_type = "vla_config"

    def __init__(
        self,
        action_hidden_size: int = 2048,
        state_hidden_size: int = 2048,
        num_experts: int = 4,
        experts=None,
        dof_config=None,
        agent_pos_config=None,
        noise_scheduler=None,
        dim_inputs: tuple = (1536, 1536),
        action_mlp_intermediate_size: int = 1536,
        mlp_moe: bool = False,
        norm_moe: bool = False,
        use_mot: bool = False,
        mot_opt: bool = False,
        ar_loss_weight: float = 1.0,
        use_state_string_representation: bool = False,
        use_adarms: bool = True,
        proj_with_mask: bool = True,
        adarms_cond_dim=None,
        action_horizon_flow: int = 32,
        causal_action_attention_mask: bool = True,
        use_flow_action_expert: bool = True,
        use_x_pred: bool = False,
        attn_deterministic: bool = False,
        use_x_loss: bool = False,
        action_linear_attention: bool = True,
        num_flow_samples: int = 1,
        rtc_train=None,
        use_per_token_tau: bool = False,
        rtc_rope_gap: int = 0,
        refiner=None,
        **kwargs,
    ):
        super().__init__(**kwargs)

        self.action_hidden_size = action_hidden_size
        self.state_hidden_size = state_hidden_size
        self.num_experts = num_experts
        self.experts = experts
        self.dof_config = dof_config
        self.agent_pos_config = agent_pos_config
        self.noise_scheduler = noise_scheduler
        self.dim_inputs = tuple(dim_inputs)
        self.action_mlp_intermediate_size = action_mlp_intermediate_size
        self.use_mot = use_mot
        self.mlp_moe = mlp_moe
        self.norm_moe = norm_moe
        self.mot_opt = mot_opt
        self.ar_loss_weight = ar_loss_weight
        self.use_state_string_representation = use_state_string_representation
        self.use_adarms = use_adarms
        self.proj_with_mask = proj_with_mask
        self.adarms_cond_dim = (
            adarms_cond_dim if adarms_cond_dim is not None else action_hidden_size
        )
        self.action_horizon_flow = action_horizon_flow
        self.causal_action_attention_mask = causal_action_attention_mask
        self.use_flow_action_expert = use_flow_action_expert
        self.use_x_pred = use_x_pred
        self.attn_deterministic = attn_deterministic
        self.use_x_loss = use_x_loss
        self.action_linear_attention = action_linear_attention
        self.num_flow_samples = num_flow_samples
        self.rtc_train = rtc_train
        self.use_per_token_tau = use_per_token_tau
        self.rtc_rope_gap = rtc_rope_gap
