class Qwen3_5DinoVisionConfig(PreTrainedConfig):
    """DINOv3 encoder plus a per-patch projector exposed as a Qwen vision tower."""

    model_type = "qwen3_5_dino_vision"
    base_config_key = "vision_config"

    def __init__(
        self,
        encoder_config=None,
        projector_config=None,
        in_channels=3,
        patch_size=16,
        spatial_merge_size=1,
        temporal_patch_size=1,
        out_hidden_size=3584,
        _attn_implementation="sdpa",
        **kwargs,
    ):
        super().__init__(**kwargs)
        if not isinstance(encoder_config, dict):
            raise ValueError("DINO vision requires an encoder_config dictionary")
        if not isinstance(projector_config, dict):
            raise ValueError("DINO vision requires a projector_config dictionary")

        from transformers import AutoConfig

        encoder_type = encoder_config.get("model_type")
        if not encoder_type:
            raise ValueError("DINO encoder_config requires model_type")
        encoder_kwargs = {
            key: value for key, value in encoder_config.items() if key != "model_type"
        }
        self.encoder_config = AutoConfig.for_model(encoder_type, **encoder_kwargs)
        self.projector_config = dict(projector_config)
        self.in_channels = int(in_channels)
        self.patch_size = int(patch_size)
        self.spatial_merge_size = int(spatial_merge_size)
        self.temporal_patch_size = int(temporal_patch_size)
        self.out_hidden_size = int(out_hidden_size)
        self._attn_implementation = _attn_implementation

        encoder_patch = int(self.encoder_config.patch_size)
        encoder_channels = int(self.encoder_config.num_channels)
        if self.patch_size != encoder_patch:
            raise ValueError(
                f"DINO patch_size mismatch: tower={self.patch_size}, "
                f"encoder={encoder_patch}"
            )
        if self.in_channels != encoder_channels:
            raise ValueError(
                f"DINO channel mismatch: tower={self.in_channels}, "
                f"encoder={encoder_channels}"
            )
        if self.spatial_merge_size not in (1, 2):
            raise ValueError(
                f"DINO projector supports spatial_merge_size 1 (per-patch) or "
                f"2 (2x2 merge), got {self.spatial_merge_size}"
            )
        if self.temporal_patch_size != 1:
            raise ValueError("2D DINO encoder requires temporal_patch_size=1")
        if self.projector_config.get("projector_type") != "per_patch_mlp":
            raise ValueError("DINO vision currently supports only per_patch_mlp")


class Qwen3_5Config(PreTrainedConfig):
    r"""
    This is the configuration class to store the configuration of a [`Qwen3_5Model`]. It is used to instantiate a
    Qwen3.5 model according to the specified arguments, defining the model architecture. Instantiating a configuration
    with the defaults will yield a similar configuration to that of
    Qwen3.5-9B-Instruct [Qwen/Qwen3.5-9B-Instruct](https://huggingface.co/Qwen/Qwen3.5-9B-Instruct).

    Configuration objects inherit from [`PreTrainedConfig`] and can be used to control the model outputs. Read the
    documentation from [`PreTrainedConfig`] for more information.


    Args:
        text_config (`Union[PreTrainedConfig, dict]`, *optional*, defaults to `Qwen3_5TextConfig`):
            The config object or dictionary of the text backbone.
        vision_config (`Union[PreTrainedConfig, dict]`,  *optional*, defaults to `Qwen3_5VisionConfig`):
            The config object or dictionary of the vision backbone.
        vla_config (`Union[VLAConfig, dict]`, *optional*, defaults to `VLAConfig`):
            The config object or dictionary for VLA (Vision-Language-Action) specific parameters.
            This sub-config centralizes all action, state, flow-matching and MoE settings needed
            when extending the VLM into a VLA model. It is nested inside `text_config` and can be
            accessed via `config.text_config.vla_config`.
        image_token_id (`int`, *optional*, defaults to 248056):
            The image token index to encode the image prompt.
        video_token_id (`int`, *optional*, defaults to 248057):
            The video token index to encode the image prompt.
        vision_start_token_id (`int`, *optional*, defaults to 248053):
            The start token index to encode the image prompt.
        vision_end_token_id (`int`, *optional*, defaults to 248054):
            The end token index to encode the image prompt.
        tie_word_embeddings (`bool`, *optional*, defaults to `False`):
            Whether to tie the word embeddings.

    ```python
    >>> from wall_x.model.qact.qwen3_5.configuration_qwen3_5 import Qwen3_5Config, VLAConfig

    >>> # Initializing a Qwen3.5 style configuration
    >>> configuration = Qwen3_5Config()

    >>> # Initializing a model with custom VLA parameters (nested inside text_config)
    >>> vla_cfg = VLAConfig(action_hidden_size=1024, dof_config={"arm": 7, "gripper": 1})
    >>> configuration = Qwen3_5Config(text_config={"vla_config": vla_cfg})

    >>> # Accessing the VLA configuration
    >>> configuration.text_config.vla_config.action_hidden_size
    ```"""

    model_type = "qwen3_5"
    sub_configs = {
        "vision_config": Qwen3_5VisionConfig,
        "text_config": Qwen3_5TextConfig,
        "vla_config": VLAConfig,
    }
    keys_to_ignore_at_inference = ["past_key_values"]

    def __init__(
        self,
        text_config=None,
        vision_config=None,
        vla_config=None,
        image_token_id=248056,
        video_token_id=248057,
        vision_start_token_id=248053,
        vision_end_token_id=248054,
        tie_word_embeddings=False,
        _attn_implementation="flash_attention_2",
        **kwargs,
    ):
        self._skip_validation = (
            text_config is None and vision_config is None and vla_config is None
        )

        if isinstance(vla_config, dict):
            self.vla_config = self.sub_configs["vla_config"](**vla_config)
            if isinstance(text_config, dict):
                text_config.update({"vla_config": self.vla_config})
        elif vla_config is None:
            self.vla_config = self.sub_configs["vla_config"]()
        else:
            self.vla_config = vla_config

        if isinstance(text_config, dict):
            self.text_config = self.sub_configs["text_config"](**text_config)
        elif text_config is None:
            self.text_config = self.sub_configs["text_config"]()
        else:
            self.text_config = text_config

        # 避免vision config的attention implementation被覆盖
        # 根据 model_type 分发到对应的 vision config 类
        if isinstance(vision_config, dict):
            _vision_model_type = vision_config.get("model_type", "qwen3_5")
            if _vision_model_type == "qwen3_5_vla_vision":
                from wall_x.model.qact.qwen3_5.qwen3_5_vla_vision import (
                    Qwen3_5VLAVisionConfig,
                )

                self.vision_config = Qwen3_5VLAVisionConfig(**vision_config)
            elif _vision_model_type == "qwen3_5_dino_vision":
                self.vision_config = Qwen3_5DinoVisionConfig(**vision_config)
            else:
                self.vision_config = self.sub_configs["vision_config"](**vision_config)
        elif vision_config is None:
            self.vision_config = self.sub_configs["vision_config"]()
        else:
            self.vision_config = vision_config

        # 确保顶层 vla_config 与 text_config.vla_config 是同一个对象
        if hasattr(self.text_config, "vla_config"):
            self.vla_config = self.text_config.vla_config
        else:
            self.text_config.vla_config = self.vla_config

        self.image_token_id = image_token_id
        self.video_token_id = video_token_id
        self.vision_start_token_id = vision_start_token_id
        self.vision_end_token_id = vision_end_token_id
        self.tie_word_embeddings = tie_word_embeddings
        super().__init__(**kwargs, _attn_implementation=_attn_implementation)
        self.attn_deterministic = getattr(self.vla_config, "attn_deterministic", False)
        self.text_config.attn_deterministic = self.attn_deterministic
        self.vision_config.attn_deterministic = self.attn_deterministic
        self._validate_config()

        # Capability decides the vision attention backend: flash-attn 2 when
        # installed and usable, otherwise PyTorch SDPA. No switches.
        from transformers.utils import is_flash_attn_2_available

        self.vision_config._attn_implementation = (
            "flash_attention_2" if is_flash_attn_2_available() else "sdpa"
        )

    def _validate_config(self):
        if self._skip_validation:
            return

        # vla_config.dim_inputs[0] 必须与 text hidden_size 匹配
        if self.vla_config.dim_inputs[0] != self.text_config.hidden_size:
            raise ValueError(
                f"`vla_config.dim_inputs[0]` ({self.vla_config.dim_inputs[0]}) "
                f"must equal `text_config.hidden_size` ({self.text_config.hidden_size})."
            )
        if self.vision_config.out_hidden_size != self.text_config.hidden_size:
            raise ValueError(
                f"`vision_config.out_hidden_size` "
                f"({self.vision_config.out_hidden_size}) must equal "
                f"`text_config.hidden_size` ({self.text_config.hidden_size})."
            )

        # use_adarms must be enabled. flash_attention_2 cannot support
        # non-causal action masks in this implementation.
        if not self.vla_config.use_adarms:
            raise ValueError("`vla_config.use_adarms` must be True.")
        if (
            self._attn_implementation == "flash_attention_2"
            and not self.vla_config.causal_action_attention_mask
        ):
            raise ValueError(
                "`vla_config.causal_action_attention_mask` must be True when "
                "`_attn_implementation` is `flash_attention_2`."
            )

        # 开启flash mask attention情况下，action linear attention应该处于关闭状态
        if (
            self._attn_implementation in {"flash_mask", "flash_mask_ki"}
            and self.vla_config.action_linear_attention
        ):
            raise ValueError(
                "`vla_config.action_linear_attention` must be False when "
                "`_attn_implementation` is `flash_mask` or `flash_mask_ki`."
            )

    def update_model_config(self, train_config):
        data_config = train_config.get("data", train_config)
        self.vla_config.use_state_string_representation = data_config.get(
            "use_state_string_representation", False
        )
        self.vla_config.ar_loss_weight = train_config.get("ar_loss_weight", 1.0)
        self.vla_config.dof_config = train_config["dof_config"]
        self.vla_config.agent_pos_config = train_config["agent_pos_config"]
        self.vla_config.action_horizon_flow = data_config.get("action_horizon_flow", 32)
        self.vla_config.num_flow_samples = data_config.get("num_flow_samples", 1)
        self.vla_config.rtc_train = data_config.get("rtc_train", None)
        self.vla_config.use_per_token_tau = data_config.get("use_per_token_tau", False)
        self.vla_config.rtc_rope_gap = data_config.get("rtc_rope_gap", 0)

        attn_impl = train_config.get(
            "_attn_implementation", train_config.get("attn_implementation")
        )
        if attn_impl is not None:
            self._attn_implementation = attn_impl

        # attn_deterministic derived from the single hyperparams.deterministic_algorithms
        # switch (MR !556 review) — one knob turns determinism on across all paths.
        attn_deterministic = train_config.get("hyperparams", {}).get(
            "deterministic_algorithms", False
        )
        self.attn_deterministic = attn_deterministic
        self.text_config.attn_deterministic = attn_deterministic
        self.vision_config.attn_deterministic = attn_deterministic
        self.vla_config.attn_deterministic = attn_deterministic
        if attn_deterministic:
            os.environ["FLASH_ATTENTION_DETERMINISTIC"] = "1"
        else:
            os.environ.pop("FLASH_ATTENTION_DETERMINISTIC", None)

        # The training YAML may override the backend loaded from config.json;
        # validate the effective configuration rather than only the original.
        self._validate_config()

    @property
    def use_state_string_representation(self):
        return self.vla_config.use_state_string_representation

    @property
    def vocab_size(self):
        return self.text_config.vocab_size

    @property
    def ar_loss_weight(self):
        return self.vla_config.ar_loss_weight


__all__ = [
    "Qwen3_5Config",
    "Qwen3_5DinoVisionConfig",
    "Qwen3_5TextConfig",
    "VLAConfig",
]
